  FT["PH-H10039"] = {"id":"PH-H10039","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11609_2021.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Compostela市","en":"An Act Establishing the Second District Engineering Office in the Municipality of Compostela, Province of Davao De Oro, and Appropriating Funds Therefor","orig":"An Act Establishing the Second District Engineering Office in the Municipality of Compostela, Province of Davao De Oro, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Văn phòng Kỹ thuật Second District tại Đô thị Compostela, Tỉnh Davao De Oro, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งสำนักงานวิศวกรรมศาสตร์ Second District ในเทศบาล Compostela จังหวัด Davao De Oro และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Kantor Teknik Second District di Kotamadya Compostela, Provinsi Davao De Oro, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Pejabat Kejuruteraan Second District di Perbandaran Compostela, Wilayah Davao De Oro, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11609","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11609_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10039-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Public Works and Highways, a district engineering office to be located in the Municipality of Compostela, Province of Davao de Oro, to be known as the Second District Engineering Office."}},{"id":"PH-H10039-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Second District Engineering Office shall serve the municipalities of Monkayo, Compostela, New Bataan, Montevista, and Maragusan, all located in the First Legislative District of the Province of Davao de Oro."}},{"id":"PH-H10039-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the operationalization of the Second District Engineering Office of the Province of Davao de Oro, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10039-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143"};
  FT["PH-H10040"] = {"id":"PH-H10040","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11610_2021.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立伊利甘市区工程办公室并为此拨款的法案","en":"An Act Creating the Iligan City District Engineering Office and Appropriating Funds Therefor","orig":"An Act Creating the Iligan City District Engineering Office and Appropriating Funds Therefor","vi":"Đạo luật thành lập Văn phòng Kỹ thuật Iligan City District, và phân bổ kinh phí","th":"พระราชบัญญัติจัดตั้งสำนักงานวิศวกรรมศาสตร์ Iligan City District และจัดสรรงบประมาณ","id":"Undang-Undang membentuk Kantor Teknik Iligan City District, dan mengalokasikan dana","ms":"Akta menubuhkan Pejabat Kejuruteraan Iligan City District, dan memperuntukkan dana"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11610","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11610_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10040-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"A district engineering office is hereby created in the Lone Legislative District of the City of Iligan to be known as the Iligan City District Engineering Office."}},{"id":"PH-H10040-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Public Works and Highways shall include in the Department’s program the operationalization of the separate district engineering office of the City of Iligan, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10040-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Iligan City District Engineering Office and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10041"] = {"id":"PH-H10041","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11611_2021.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将北拉瑙省北拉瑙区工程办公室重组为两个单独的区工程办公室并为其拨款","en":"An Act Reconstituting the Lanao Del Norte District Engineering Office in the Province of Lanao Del Norte Into Two (2) Separate District Engineering Offices, and Appropriating Funds Therefor","orig":"An Act Reconstituting the Lanao Del Norte District Engineering Office in the Province of Lanao Del Norte Into Two (2) Separate District Engineering Offices, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11611","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11611_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10041-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Lanao del Norte District Engineering Office, under the supervision of the Department of Public Works and Highways, shall be reconstituted into two (2) separate district engineering offices to be named as Lanao del Norte First Engineering Office and Lanao del Norte Second District Engineering Office, respectively."}},{"id":"PH-H10041-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Lanao del Norte First Engineering Office which shall be located within the First Congressional District of the Province of Lanao del Norte shall serve the municipalities of Baroy, Tubod, Kolambugan, Maigo, Bacolod, Kauswagan, Linamon, Tagoloan, Baloi, Matunggao and Pantar. The Lanao del Norte Second District Engineering Office which shall be located within the Second Congressional District shall serve the municipalities of Pantao Ragat, Poona Piagapo, Munai, Tangkal, Magsaysay, Salvador, Lala, Sultan Naga Dimaporo (SND), Kapatagan, Sapad and Nunungan."}},{"id":"PH-H10041-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of the Department of Public Works and Highways shall include in the Department’s program the operationalization of the Lanao del Norte First and Second District Offices, the initial funding of which shall be charged against the current year’s appropriations of the Lanao del Norte District Engineering Office. Thereafter, the amount necessary for the continued operation of the said district engineering offices shall be included in the annual General Appropriations Act."}},{"id":"PH-H10041-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Republic Act No. 9035, constituting the inland, interior and remotely-situated municipalities of the Province of Lanao del Norte into a separate highway engineering district is hereby repealed accordingly."}},{"id":"PH-H10041-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reconstituting the Lanao Del Norte District Engineering Office in the Province of Lanao Del Norte Into Two (2) Separate District Engineering Offices, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10042"] = {"id":"PH-H10042","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11612_2021.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在北三宝颜省第三立法区设立新的区工程办公室并为此拨款的法案","en":"An Act Creating a New District Engineering Office in the Third Legislative District of the Province of Zamboanga Del Norte and Appropriating Funds Therefor","orig":"An Act Creating a New District Engineering Office in the Third Legislative District of the Province of Zamboanga Del Norte and Appropriating Funds Therefor","vi":"Đạo luật thành lập Văn phòng Kỹ thuật New District tại Quận Province Zamboanga Del Norte, và phân bổ kinh phí","th":"พระราชบัญญัติจัดตั้งสำนักงานวิศวกรรมศาสตร์ New District ในเขต Province Zamboanga Del Norte และจัดสรรงบประมาณ","id":"Undang-Undang membentuk Kantor Teknik New District di Distrik Province Zamboanga Del Norte, dan mengalokasikan dana","ms":"Akta menubuhkan Pejabat Kejuruteraan New District di Daerah Province Zamboanga Del Norte, dan memperuntukkan dana"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 11612","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11612_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10042-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Public Works and Highways, an additional district engineering office for the Third Legislative District of the Province of Zamboanga del Norte. It shall be known as the Fourth District Engineering Office and shall be located in the Municipality of Siocon, Province of Zamboanga del Norte."}},{"id":"PH-H10042-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Fourth District Engineering Office shall serve the municipalities of Baliguian, Siraway, Siocon, and Sibuco, all within the Third Legislative District of the Province of Zamboanga del Norte."}},{"id":"PH-H10042-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of the Department of Public Works and Highways shall include in the Department’s program the operationalization of the Fourth District Engineering Office in the Province of Zamboanga del Norte, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10042-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating a New District Engineering Office in the Third Legislative District of the Province of Zamboanga Del Norte and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10043"] = {"id":"PH-H10043","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11613_2021.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Baybay市","en":"An Act Establishing a National High School in Barangay Maganhan, City of Baybay, Province of Leyte to Be Known as Maganhan National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Maganhan, City of Baybay, Province of Leyte to Be Known as Maganhan National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Maganhan, Thành phố Baybay, Tỉnh Leyte được biết đến với tên gọi Trường trung học phổ thông quốc gia Maganhan","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Maganhan, เมือง Baybay, จังหวัด Leyte ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Maganhan","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Maganhan, Kota Baybay, Provinsi Leyte dikenal sebagai Sekolah Menengah Atas Nasional Maganhan","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Maganhan, Bandaraya Baybay, Wilayah Leyte dikenali sebagai Sekolah Menengah Kebangsaan Maganhan"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 11613","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11613_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10043-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education (DepEd), a national high school in Barangay Maganhan, City of Baybay, Province of Leyte to be known as Maganhan National High School."}},{"id":"PH-H10043-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary for the operationalization of the Maganhan National High School shall be charged against those authorized in the current appropriations of the DepEd. Thereafter, the amount necessary for the implementation of this Act shall be included in the Annual General Appropriations Act."}},{"id":"PH-H10043-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Within one hundred twenty (120) days from the approval of this Act, the DepEd, in coordination with the local governments of the City of Baybay and Barangay Maganhan, shall issue rules and regulations implementing the provisions of this Act."}},{"id":"PH-H10043-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All other laws, decrees, executive orders, rules and regulations, other issuances inconsistent with this Act are hereby repealed or amended accordingly."}},{"id":"PH-H10043-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143"};
  FT["PH-H10044"] = {"id":"PH-H10044","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11614_2021.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在莱特省Baybay市Punta描笼涯设立国立中学，名称为Punta国立中学，并为此拨款的法案","en":"An Act Establishing a National High School in Barangay Punta, Baybay City, Province of Leyte to Be Known as Punta National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Punta, Baybay City, Province of Leyte to Be Known as Punta National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Punta, Baybay City, Tỉnh Leyte được biết đến với tên gọi Trường trung học phổ thông quốc gia Punta","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Punta, Baybay City, จังหวัด Leyte ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Punta","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Punta, Baybay City, Provinsi Leyte dikenal sebagai Sekolah Menengah Atas Nasional Punta","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Punta, Baybay City, Wilayah Leyte dikenali sebagai Sekolah Menengah Kebangsaan Punta"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 11614","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11614_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10044-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education (DepEd), a national high school in Barangay Punta, Baybay City, Province of Leyte to be known as the Punta National High School."}},{"id":"PH-H10044-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education shall immediately include in the Department’s program the operationalization of the Punta National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10044-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Within one hundred twenty (120) days from the approval of this Act, the Secretary of Education shall formulate the rules and regulations implementing the provisions of this Act."}},{"id":"PH-H10044-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a National High School in Barangay Punta, Baybay City, Province of Leyte to Be Known as Punta National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H10045"] = {"id":"PH-H10045","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11615_2021.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Malita市","en":"An Act Establishing a National High School in Barangay Talogoy, Municipality of Malita, Province of Davao Occidental, to Be Known as Tamaing Tribal National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Talogoy, Municipality of Malita, Province of Davao Occidental, to Be Known as Tamaing Tribal National High School, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Talogoy, Thị trấn Malita, Tỉnh Davao Occidental được biết đến với tên gọi Trường trung học phổ thông quốc gia Tamaing Tribal","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Talogoy, เทศบาล Malita, จังหวัด Davao Occidental ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Tamaing Tribal","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Talogoy, Kotamadya Malita, Provinsi Davao Occidental dikenal sebagai Sekolah Menengah Atas Nasional Tamaing Tribal","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Talogoy, Perbandaran Malita, Wilayah Davao Occidental dikenali sebagai Sekolah Menengah Kebangsaan Tamaing Tribal"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 11615","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11615_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10045-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education (DepEd), a national high school in Barangay Talogoy, Municipality of Malita, Province of Davao Occidental to be known as the Tamaing Tribal National High School."}},{"id":"PH-H10045-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education shall immediately include in the Department’s program the operationalization of the Tamaing Tribal National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H10045-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Within one hundred twenty (120) days from the approval of this Act, the Secretary of Education shall formulate the rules and regulations implementing the provisions of this Act."}},{"id":"PH-H10045-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143"};
  FT["PH-H10046"] = {"id":"PH-H10046","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2021/ra_11616_2021.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将西达沃省 Don Marcelino 市镇 Lawa 描笼涯的 Lawa 国立中学分校分离，改设为独立的 Corona A. Cabanilla 国立中学，并为此拨付所需经费","en":"An Act Separating the Lawa National High School-Nueva Villa Extension in Barangay Lawa, Municipality of Don Marcelino, Province of Davao Occidental From the Lawa National High School, Converting It Into An Independent National High School to Be Known as Corona A. Cabanilla National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Lawa National High School-Nueva Villa Extension in Barangay Lawa, Municipality of Don Marcelino, Province of Davao Occidental From the Lawa National High School, Converting It Into An Independent National High School to Be Known as Corona A. Cabanilla National High School, and Appropriating Funds Therefor","vi":"Đạo luật tách Phân hiệu Nueva Villa của Trường Trung học Lawa Quốc gia tại Barangay Lawa, Đô thị Don Marcelino, Tỉnh Davao Occidental khỏi Trường Trung học Lawa Quốc gia và chuyển thành Trường Trung học Độc lập Quốc gia với tên gọi Trường Trung học Corona A. Cabanilla Quốc gia, và bố trí kinh phí","th":"พระราชบัญญัติแยกวิทยาเขต Nueva Villa ของโรงเรียนมัธยมศึกษา Lawa แห่งชาติในบารังไกย์ Lawa เทศบาล Don Marcelino จังหวัด Davao Occidental ออกจากโรงเรียนมัธยมศึกษา Lawa แห่งชาติและยกฐานะเป็นโรงเรียนมัธยมศึกษาเอกเทศแห่งชาติชื่อโรงเรียนมัธยมศึกษา Corona A. Cabanilla แห่งชาติ และจัดสรรงบประมาณ","id":"Undang-Undang Memisahkan Kampus Nueva Villa, Sekolah Menengah Lawa Nasional di Barangay Lawa, Kotamadya Don Marcelino, Provinsi Davao Occidental dari Sekolah Menengah Lawa Nasional dan menjadi Sekolah Menengah Mandiri Nasional dengan nama Sekolah Menengah Corona A. Cabanilla Nasional, dan mengalokasikan dana","ms":"Akta Memisahkan Kampus Nueva Villa, Sekolah Menengah Lawa Kebangsaan di Barangay Lawa, Perbandaran Don Marcelino, Wilayah Davao Occidental daripada Sekolah Menengah Lawa Kebangsaan dan menjadi Sekolah Menengah Bebas Kebangsaan dengan nama Sekolah Menengah Corona A. Cabanilla Kebangsaan, dan memperuntukkan dana"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 11616","issuingBody":"Congress of the Philippines","promulgatedDate":"2021-12-10","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2021/ra_11616_2021.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10046-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Lawa National High School-Nueva Villa Extension in Barangay Lawa, Municipality of Don Marcelino, Province of Davao Occidental is hereby separated from the Lawa National High School and converted it into a national high school to be known as Corona A. Cabanilla National High School."}},{"id":"PH-H10046-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities and records of the Lawa National High School-Nueva Villa Extension are hereby transferred to and absorbed by the Corona A. Cabanilla National High School."}},{"id":"PH-H10046-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department’s program the operationalization of the Corona A. Cabanilla National High School, the initial funding of which shall be charged against the current year’s appropriation of the Lawa National High School – Nueva Villa Extension. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H10046-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Within one hundred twenty (120) days after the approval of this Act, the Secretary of Education shall promulgate the rules and regulations implementing the provisions of this Act."}},{"id":"PH-H10046-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Lawa National High School-Nueva Villa Extension in Barangay Lawa, Municipality of Don Marcelino, Province of Davao Occidental From the Lawa National High School, Converting It Into An Independent National High School to Be Known as Corona A. Cabanilla National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
