  FT["PH-H10085"] = {"id":"PH-H10085","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11657_2022.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将东达沃省 Mati 市 Libudon 国立中学－Shanghay 附属校从该校分离，改设为名为 Shanghay 国立中学的独立国立中学并拨款","en":"An Act Separating the Libudon National High School - Shanghay, Mati City, Province of Davao Oriental from the Libudon National High School, Converting it into an Independent National High School to be Known as Shanghay National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Libudon National High School - Shanghay, Mati City, Province of Davao Oriental from the Libudon National High School, Converting it into an Independent National High School to be Known as Shanghay National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 11657","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-03-11","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11657_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10085-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Libudon National High School - Sanghay Extension in Barangay Sanghay, Mati City, Province of Davao Oriental is hereby separated from the Libudon National High School and converted into an independent national high school to be known as Sanghay National High School."}},{"id":"PH-H10085-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel, assets, liabilities and records of the Libudon National High School - Sanghay Extension are hereby transferred to and absorbed by the Sanghay National High School."}},{"id":"PH-H10085-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education shall immediately include in the Department's program the operationalization of the Sanghay National High School, the initial funding of which shall be charged against the current year's appropriation of the Libudon National High School - Sanghay Extension. Thereafter, the amount necessary for the continued operation of the school shall be included in the annual General Appropriations Act."}},{"id":"PH-H10085-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Within sixty (60) days after the approval of this Act, the Secretary of Education shall formulate the rules and regulations implementing the provisions of this Act."}},{"id":"PH-H10085-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Libudon National High School - Shanghay, Mati City, Province of Davao Oriental from the Libudon National High School, Converting it into an Independent National High School to be Known as Shanghay National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
