  FT["PH-H10088"] = {"id":"PH-H10088","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2022/ra_11660_2022.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Elizabeth Eder Zobel de Ayala菲律宾公民身份、使其归化为菲律宾公民并享有公民权利的法案","en":"An Act Granting Philipine Citizenship to Elizabeth Eder Zobel de Ayala","orig":"An Act Granting Philipine Citizenship to Elizabeth Eder Zobel de Ayala"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 11660","issuingBody":"Congress of the Philippines","promulgatedDate":"2022-03-29","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2022/ra_11660_2022.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H10088-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Mrs. Elizabeth Eder Zobel de Ayala is hereby granted Philippine citizenship with all the rights, privileges, and prerogatives, as well as duties and obligations appurtenant thereto under the Constitution and the laws of the Republic of the Philippines."}},{"id":"PH-H10088-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Mrs. Elizabeth Eder Zobel de Ayala shall take the Oath of Allegiance to the Republic of the Philippines before an officer duly authorized to administer the same. The Oath of Allegiance shall be registered with the Bureau of Immigration."}},{"id":"PH-H10088-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Upon registration of the Oath of Allegiance, the Bureau of Immigration shall issue a Certificate of Naturalization to Mrs. Elizabeth Eder Zobel de Ayala who shall thereupon enter into the full enjoyment of Philippine citizenship."}},{"id":"PH-H10088-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p143","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Philipine Citizenship to Elizabeth Eder Zobel de Ayala","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
